import os,json,subprocess
from pathlib import Path
old=Path("/srv/fadego-staging")
root=Path("/srv/projects/fadego")
unit=Path("/etc/systemd/system/fadego-staging.service")
out={"component":"fadego-staging-legacy-alias","status":"BLOCKED","changed":False}
def proc(args):
 return subprocess.run(args,capture_output=True,text=True,timeout=10)
def statuses():
 names=("ssh","nginx","fadego-staging","lowcost-europa","pink-iptv-backend","pm2-root")
 return {n:proc(["systemctl","is-active",n]).stdout.strip() for n in names}
removed=False
try:
 if not old.is_symlink() or old.resolve(strict=True)!=root or not root.is_dir() or root.is_symlink():raise RuntimeError("old_alias_or_project_root_invalid")
 if not unit.is_file() or "/srv/fadego-staging" in unit.read_text(errors="replace"):raise RuntimeError("service_unit_still_uses_alias")
 p=proc(["systemctl","show","fadego-staging","--property=ExecStart,WorkingDirectory,EnvironmentFiles"])
 if p.returncode!=0 or old.as_posix() in p.stdout:raise RuntimeError("runtime_unit_still_uses_alias")
 for d in Path("/proc").iterdir():
  if not d.name.isdecimal():continue
  try:
   cwd=os.readlink(str(d/"cwd"));exe=os.readlink(str(d/"exe"))
   if old.as_posix() in (cwd,exe) or cwd.startswith(old.as_posix()+"/") or exe.startswith(old.as_posix()+"/"):raise RuntimeError("live_process_uses_alias")
  except (OSError,PermissionError):pass
 if proc(["nginx","-t"]).returncode!=0:raise RuntimeError("nginx_invalid_before")
 before=statuses()
 old.unlink();removed=True
 if old.exists() or old.is_symlink() or proc(["nginx","-t"]).returncode!=0 or statuses()!=before:raise RuntimeError("postcheck_failed")
 out.update(status="ALIAS_REMOVED_VERIFIED",changed=True,project_root=str(root),old_alias_absent=True,protected_services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:180]
 if removed and not old.exists() and not old.is_symlink():
  try:old.symlink_to(root);out["rollback"]="RESTORED_ALIAS"
  except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="ALIAS_REMOVED_VERIFIED":raise SystemExit(3)
